A.army={w:['hunter'],ic:'👥',n:'กองทัพจากศัตรูที่ล้ม',ok:M=>M.H&&M.H.aw&&S.age>=19&&(H().sysH||P(.35)),gap:[2,4],st:[
 F=>{const s=SOL[0];ask('👥 “ลุกขึ้น”',`${tag('🌀 ฮันเตอร์')}<br>คุณล้ม${s[1]}ที่เฝ้าเกตลงได้ ร่างของมันยังไม่สลาย มีคำหนึ่งลอยขึ้นมาในหัว — <b>ลุกขึ้น</b>`,[
  ['พูดคำนั้น','มินิเกม: กดรัวดึงวิญญาณ',()=>mg('mash','👥 ดึงวิญญาณ','กดรัวดึงวิญญาณออกจากร่างก่อนมันสลาย',{a:'คุณ',b:'การสลาย',ic:'🖤',foe:.95},sc=>{if(sc>=1){H().army.push({ic:s[0],n:s[1],lv:1});eff({pow:6},`🖤 <b>${s[1]}ลุกขึ้นคุกเข่าต่อหน้าคุณ</b> ดวงตาของมันลุกเป็นไฟสีม่วง`,'myth');kAdd('ได้ทหารเงาตัวแรก')}else eff({},'🌫️ วิญญาณสลายไปก่อน แต่มันหันมามองคุณครั้งสุดท้าย')})],
  ['เดินจากไป','',()=>{F.no=1}]])},
 F=>{if(F.no)return;const op=SOL.slice(1,4);ask('👥 เลือกทหารคนต่อไป','บอสสามตัวในเกตเดียว คุณมีแรงดึงวิญญาณได้ตัวเดียว',op.map(s=>[`${s[0]} ${s[1]}`,'',()=>mg('mash',`${s[0]} ดึงวิญญาณ`,'กดรัวให้ทัน',{b:'การสลาย',ic:'🖤',foe:1.1},sc=>{if(sc>=1){H().army.push({ic:s[0],n:s[1],lv:1});eff({pow:5},`🖤 ${s[1]}เข้าร่วมกองทัพ`,'epic')}else eff({},'🌫️ วิญญาณหลุดมือไป')})]))},
 F=>{const a=H().army;if(!a.length)return;const s=a[0];ask(`🖤 ${s.n}พูดได้`,`${s.n}ที่ติดตามคุณมาหลายปีคุกเข่าลง แล้ว<b>พูดเป็นภาษามนุษย์</b>เป็นครั้งแรก<br>“ข้าจำได้แล้ว ข้าเคยเป็นฮันเตอร์ ข้ามีลูกสาวรออยู่ข้างนอกเกต… ปล่อยข้าไปหานางเถิด”`,[
  ['ปล่อยเขาไป','กองทัพเล็กลง',()=>{F.free=1;s.free=1;H().army=a.filter(x=>x!==s);eff({karma:15,pow:-4},`🕊️ ${s.n}สลายเป็นควันสีม่วง ลอยออกไปทางหน้าต่าง`,'epic')}],
  ['“เจ้าเป็นของข้าแล้ว”','',()=>{s.lv+=2;eff({pow:8,karma:-10},`⛓️ ดวงตาของ${s.n}ดับลงชั่วครู่ แล้วลุกขึ้นใหม่ เงียบกว่าเดิม`,'bad')}]])},
 F=>ask('🌊 เกตแตกกลางเมือง',`เกตแรงก์ S แตกกลางเมือง มอนสเตอร์นับพันไหลออกมา กองทัพของคุณ${H().army.length?`มี ${H().army.length} ตน`:'ไม่เหลือแล้ว'}`,[
  ['นำกองทัพลงสนาม','มินิเกม: แตะเป้า',()=>mg('tap','🌊 เกตแตก','แตะมอนสเตอร์ให้มากที่สุด',{n:14,ic:'👹',ms:950},sc=>{const b=F.free?.25:0,w=sc+b+H().army.length*.05>=.7;eff(w?{fame:3000,pow:8}:{hp:-40,fame:500},w?(F.free?`🌊 กลางสนามรบ ทหารม่วงตนหนึ่งที่คุณปล่อยไปกลับมายืนข้างคุณ พร้อมฮันเตอร์หญิงสาวที่เรียกเขาว่า “พ่อ” — <b>เกตถูกปิด</b>`:`🌊 <b>กองทัพเงาปิดเกตได้ในคืนเดียว</b> คนทั้งเมืองเห็นคุณยืนอยู่หน้ากองทัพที่ไม่มีเสียง`):'🩸 เมืองครึ่งหนึ่งพัง คุณเกือบไม่รอด',w?'myth':'bad')})]])]};
